"""Generated by solo-to-scale; edit `templates/tools/tickets.py` in the plugin, then run upgrade.

Agent coordination through GitHub issues. A ticket is an issue labelled `ticket` and `role:<role>`; its body
holds the parent and the blockers. Roles delegate, hand off, block and finish work here, and every action is
written to one activity log (an issue labelled `activity-log`) and, except for a claim, to the ticket.

  python tools/tickets.py new <role> --title "..." --goal "..." [--initiative I1 | --objective O1] [--parent N] [--blocked-by N ...] --by <role>
                                         # the initiative (founder/goals.json) becomes the label initiative:I1
                                         # and its objective goal:O1; a sub-ticket inherits its parent's. While
                                         # goals.json has active objectives, a ticket that names none is refused,
                                         # and once they have initiatives, one that names no initiative is too.
                                         # --stage N labels it stage:N (the playbook gate it works toward; inherited)
  python tools/tickets.py claim <n> --role <role>      # atomic: exactly one claimant wins
  python tools/tickets.py release <n> --role <role>
  python tools/tickets.py handoff <n> --to <role> --note "..." --by <role>
  python tools/tickets.py block <n> --on M --why "..." --by <role>   |   unblock <n> --on M --by <role>
  python tools/tickets.py done <n> --role <role> --note "..."         # closes it and wakes what it blocked
  python tools/tickets.py plan <parent> --by <role> [--note "..."]   # ask the founder to approve the sub-ticket plan
  python tools/tickets.py review <n> --verdict approved|changes --by <reviewer role> --note "..."
  python tools/tickets.py escalate <n> --by <role> --why "..."   # to the role's manager; the chief of staff's is you
  python tools/tickets.py queue <role>     # open, unclaimed, unblocked tickets for a role, oldest first
  python tools/tickets.py tree <n>         # a parent and its sub-tickets
  python tools/tickets.py log [--role R] [--ticket N] [--limit 30]
  python tools/tickets.py closed <n>       # CI, when any issue closes: release its claim, wake dependents

The claim is a git ref, `refs/claims/<n>`, created through the GitHub API. Creating a ref that exists fails, so
two agents racing for one ticket can't both win. Anything unclear refuses the claim.
With the `plan` gate set to ask in founder/gates.json, a sub-ticket can be claimed only when the founder has
approved its parent's latest plan, and only if it is in that plan: a changed plan needs approval again.
Review before done: a ticket labelled `needs-review:<role>` (from `new --review`, or founder/gates.json `review`,
e.g. engineer work reviewed by qa) can't be finished until that role's latest verdict is `approved`. The
reviewer is never the ticket's own role. Chain of command: every role reports to the chief of staff, and the
chief of staff to the founder; `escalate` labels the ticket `escalated-to:<manager>`.
Text an agent writes is quoted, so it can never read as a founder's /approve.
Python 3 standard library plus the gh CLI.
"""
from __future__ import annotations

import argparse
import json
import re
import subprocess
import sys
import urllib.parse
from pathlib import Path
from typing import Any

sys.path.insert(0, str(Path(__file__).resolve().parent))
import _s2s as s  # noqa: E402
import goals  # noqa: E402
import approval  # noqa: E402
from approval import repo_name  # noqa: E402

OK, REFUSED, ERROR = 0, 1, 5
NEEDS_REVIEW, ESCALATED, STAGE = "needs-review:", "escalated-to:", "stage:"
VERDICTS = ("approved", "changes")
REVIEW = re.compile(r"<!-- s2s:review (\{.*?\}) -->")
TICKET, CLAIMED, BLOCKED, LOG = "ticket", "claimed", "blocked", "activity-log"
CLAIM_REF = "refs/claims/"
ROLES = ("chief-of-staff", *s.ROLES)
# Chain of command (roles/*.yaml `reports_to`): blockers go to the manager first; only the chief of staff
# escalates to the founder.
REPORTS_TO = {**{r: "chief-of-staff" for r in s.ROLES}, "chief-of-staff": "founder"}
MARK = re.compile(r"<!-- s2s:activity (\{.*?\}) -->")
REF_LINE = re.compile(r"^\*\*(Parent|Blocked by):\*\*(.*)$", re.MULTILINE)


def gh(*args: str, payload: dict | None = None) -> Any:
    cmd = ["gh", "api", *args]
    if payload is not None:
        cmd += ["--input", "-"]
    out = subprocess.run(cmd, input=json.dumps(payload) if payload is not None else None,
                         capture_output=True, text=True, check=True)
    return json.loads(out.stdout or "null")


# --- ticket bodies (pure) ------------------------------------------------------------------------------

def quote(text: str) -> str:
    """Agent text as a blockquote: a line like `/approve` inside it never matches a founder command."""
    return "\n".join("> " + line for line in (text or "(not given)").splitlines()) or "> (not given)"


def numbers(text: str) -> list[int]:
    return [int(n) for n in re.findall(r"#(\d+)", text or "")]


def links(body: str) -> dict[str, list[int]]:
    found = {"parent": [], "blocked by": []}
    for key, rest in REF_LINE.findall(body or ""):
        found[key.lower()] = numbers(rest)
    return found


def set_blockers(body: str, blockers: list[int]) -> str:
    line = "**Blocked by:** " + (", ".join(f"#{n}" for n in sorted(set(blockers))) or "nothing")
    if re.search(r"^\*\*Blocked by:\*\*", body or "", re.MULTILINE):
        return re.sub(r"^\*\*Blocked by:\*\*.*$", line, body, count=1, flags=re.MULTILINE)
    return (body or "").rstrip("\n") + "\n" + line + "\n"


def ticket_body(role: str, goal: str, done_when: str, why: str, parent: int | None, blockers: list[int], by: str,
                objective: str = "", initiative: str = "") -> str:
    return "\n".join([
        f"**Role:** `role:{role}`", f"**Opened by:** `role:{by}`" if by else "**Opened by:** the founder",
        *([f"**Objective:** {objective} (label `{goals.label(objective)}`)"] if objective else []),
        *([f"**Initiative:** {initiative} (label `{goals.initiative_label(initiative)}`)"] if initiative else []),
        f"**Parent:** #{parent}" if parent else "**Parent:** none",
        "**Blocked by:** " + (", ".join(f"#{n}" for n in blockers) or "nothing"),
        "", "## Goal", quote(goal), "", "## Done when", quote(done_when), "", "## Why", quote(why), "",
        "Claim it with `python tools/tickets.py claim <n> --role " + role + "` before starting. Gated actions still go"
        " through the `gate` skill: a ticket never approves anything.",
    ])


def entry(role: str, action: str, ticket: int, why: str, **extra: Any) -> str:
    data = {"role": role, "action": action, "ticket": ticket, **extra}
    head = f"**{('role:' + role) if role in ROLES else role}** {action} #{ticket}"
    if extra.get("to"):
        head += f" → `role:{extra['to']}`"
    if extra.get("on"):
        head += f" (on #{extra['on']})"
    return f"<!-- s2s:activity {json.dumps(data, ensure_ascii=False)} -->\n{head}\n\n{quote(why)}"


def parse_log(comments: list[dict[str, Any]]) -> list[dict[str, Any]]:
    rows = []
    for c in comments:
        m = MARK.search(c.get("body") or "")
        if not m:
            continue
        try:
            data = json.loads(m.group(1))
        except ValueError:
            continue
        why = "\n".join(ln[2:] for ln in (c.get("body") or "").splitlines() if ln.startswith("> "))
        rows.append({**data, "why": why, "at": c.get("created_at", "")})
    return rows


def labels_of(issue: dict[str, Any]) -> list[str]:
    return [lb["name"] if isinstance(lb, dict) else lb for lb in issue.get("labels", [])]


def role_of(issue: dict[str, Any]) -> str:
    return next((lb[5:] for lb in labels_of(issue) if lb.startswith("role:")), "")


# --- GitHub ----------------------------------------------------------------------------------------------

class Hub:
    def __init__(self, repo: str) -> None:
        self.repo = repo
        self.root = s.ROOT  # set to --root by main(); the plan gate reads founder/gates.json from here

    def api(self, path: str, *args: str, payload: dict | None = None) -> Any:
        return gh(f"repos/{self.repo}/{path}".rstrip("/"), *args, payload=payload)

    def issue(self, n: int) -> dict[str, Any]:
        return self.api(f"issues/{n}")

    def tickets(self, state: str = "open", label: str = TICKET) -> list[dict[str, Any]]:
        found = self.api(f"issues?labels={urllib.parse.quote(label)}&state={state}&per_page=100") or []
        return sorted((i for i in found if not i.get("pull_request")), key=lambda i: i["number"])

    def label(self, n: int, *names: str) -> None:
        self.api(f"issues/{n}/labels", "-X", "POST", payload={"labels": list(names)})

    def unlabel(self, issue: dict[str, Any], *names: str) -> None:
        for name in names:
            if name in labels_of(issue):
                self.api(f"issues/{issue['number']}/labels/{urllib.parse.quote(name, safe='')}", "-X", "DELETE")

    def comment(self, n: int, body: str) -> None:
        self.api(f"issues/{n}/comments", "-X", "POST", payload={"body": body})

    def record(self, n: int, role: str, action: str, why: str, *, on_ticket: bool = True, **extra: Any) -> None:
        """One comment in the activity log and, unless on_ticket is False, one on the ticket."""
        body = entry(role, action, n, why, **extra)
        if on_ticket:
            self.comment(n, body)
        logs = self.tickets("all", LOG)
        log_n = logs[0]["number"] if logs else self.api("issues", "-X", "POST", payload={
            "title": "Activity log", "labels": [LOG],
            "body": "Who did what, and why. Written by `tools/tickets.py`; read it with `python tools/tickets.py log`."
                    " A record, never an approval."})["number"]
        self.comment(log_n, body)

    # The claim lock: a ref per ticket. Creating an existing ref fails, so only one claimant wins.
    def holder(self, n: int) -> str | None:
        try:
            ref = self.api(f"git/ref/{CLAIM_REF[5:]}{n}")
        except subprocess.CalledProcessError:
            return None
        msg = self.api(f"git/commits/{ref['object']['sha']}").get("message", "")
        m = re.search(r" by (\S+)", msg)
        return m.group(1) if m else "someone"

    def lock(self, n: int, who: str) -> str | None:
        """Take the claim. Returns None if this caller won, else who holds it. Raises if GitHub is unclear."""
        branch = self.api("").get("default_branch", "main")
        tree = self.api(f"commits/{urllib.parse.quote(branch, safe='')}")["commit"]["tree"]["sha"]
        commit = self.api("git/commits", "-X", "POST", payload={"message": f"claim #{n} by {who}", "tree": tree, "parents": []})
        try:
            self.api("git/refs", "-X", "POST", payload={"ref": f"{CLAIM_REF}{n}", "sha": commit["sha"]})
        except subprocess.CalledProcessError:
            current = self.holder(n)
            if current is None:
                raise
            return current
        return None

    def unlock(self, n: int) -> None:
        if self.holder(n) is not None:
            self.api(f"git/refs/{CLAIM_REF[5:]}{n}", "-X", "DELETE")

    def children(self, parent: int) -> list[dict[str, Any]]:
        return [i for i in self.tickets("all") if parent in links(i.get("body", ""))["parent"]]

    def wake(self, done: int, by: str) -> list[int]:
        """Unblock every open ticket whose blockers are now all closed."""
        woken = []
        for t in self.tickets("open"):
            blockers = links(t.get("body", ""))["blocked by"]
            if done not in blockers:
                continue
            if all(b == done or self.issue(b).get("state") == "closed" for b in blockers):
                self.unlabel(t, BLOCKED)
                self.record(t["number"], by, "unblocked", f"#{done} is done; nothing else blocks this.", on=done)
                woken.append(t["number"])
        return woken


# --- commands -----------------------------------------------------------------------------------------

def need_role(role: str) -> None:
    if role not in ROLES:
        raise SystemExit(f"unknown role {role!r}; roles: {', '.join(ROLES)}")


def which_objective(a: argparse.Namespace, hub: Hub) -> tuple[str, str]:
    """The ticket's (objective, initiative): --initiative (which implies its objective), else --objective, else
    its parent's labels. While founder/goals.json has active objectives a ticket must name one, and once they
    have initiatives it must name an initiative, so every piece of work traces back to the North Star."""
    data = goals.load(a.root)
    known = goals.ids(data)
    initiative = getattr(a, "initiative", "") or ""
    if initiative:
        obj = goals.initiative_objective(data, initiative)
        if not obj:
            have = sorted(str(i.get("id")) for i in goals.initiatives(data))
            raise SystemExit(f"unknown initiative {initiative!r}; founder/goals.json has: {', '.join(have) or 'none'}")
        if a.objective and a.objective != obj:
            raise SystemExit(f"initiative {initiative} serves {obj}, not {a.objective}")
        return obj, initiative
    if a.objective and a.objective not in known:
        raise SystemExit(f"unknown objective {a.objective!r}; founder/goals.json has: {', '.join(sorted(known)) or 'none'}")
    objective = a.objective
    if not objective and a.parent:
        labels = labels_of(hub.issue(a.parent))
        objective, initiative = goals.objective_of(labels), goals.initiative_of(labels)
        if objective:
            return objective, initiative
    live_inits = [i for i in goals.live_initiatives(data)
                  if not objective or goals.initiative_objective(data, str(i.get("id"))) == objective]
    if live_inits:
        raise SystemExit("name the initiative this ticket serves: --initiative "
                         + " or ".join(str(i.get("id")) for i in live_inits) + " (or give a --parent that has one)")
    if objective:
        return objective, ""
    live = [o["id"] for o in goals.active(data)]
    if live:
        raise SystemExit("name the objective this ticket serves: --objective " + " or ".join(live)
                         + " (or give a --parent that has one)")
    return "", ""


def stage_label(a: argparse.Namespace, hub: Hub) -> str:
    """`stage:<n>` from --stage, else the parent's: the autopilot counts a stage as covered by these tickets."""
    n = getattr(a, "stage", None)
    if n is not None:
        if not 1 <= n <= 30:
            raise SystemExit(f"--stage must be 1 to 30, not {n}")
        return f"{STAGE}{n}"
    if a.parent:
        return next((lb for lb in labels_of(hub.issue(a.parent)) if re.fullmatch(STAGE + r"\d{1,2}", lb)), "")
    return ""


def cmd_new(a: argparse.Namespace, hub: Hub) -> int:
    need_role(a.role)
    if a.by:
        need_role(a.by)
    blockers = sorted(set(a.blocked_by or []))
    objective, initiative = which_objective(a, hub)
    body = ticket_body(a.role, a.goal, a.done_when, a.why, a.parent, blockers, a.by, objective, initiative)
    reviewer = review_for(a, hub)
    stage = stage_label(a, hub)
    labels = [TICKET, f"role:{a.role}"] + ([stage] if stage else []) + ([BLOCKED] if blockers else []) + ([goals.label(objective)] if objective else []) \
        + ([goals.initiative_label(initiative)] if initiative else []) + ([NEEDS_REVIEW + reviewer] if reviewer else [])
    if a.dry_run:
        print(f"{a.title}\nlabels: {', '.join(labels)}\n\n{body}")
        return OK
    made = hub.api("issues", "-X", "POST", payload={"title": a.title, "body": body, "labels": labels})
    n = made["number"]
    print(f"#{n} {made.get('html_url', '')}")
    if a.parent:
        try:  # GitHub's own sub-issue link; the Parent line in the body is the record either way
            hub.api(f"issues/{a.parent}/sub_issues", "-X", "POST", payload={"sub_issue_id": made["id"]})
        except (subprocess.CalledProcessError, KeyError):
            print(f"note: couldn't link #{n} as a GitHub sub-issue of #{a.parent}; its Parent line still links them")
    hub.record(n, a.by or "founder", "opened", a.why or a.goal, to=a.role,
               **({"parent": a.parent} if a.parent else {}))
    return OK


def review_for(a: argparse.Namespace, hub: Hub) -> str:
    """Who reviews a new ticket: --review, else founder/gates.json `review` for its role; never the role itself."""
    if getattr(a, "review", "") == "none":
        return ""
    raw = s.read(hub_root(hub) / "founder" / "gates.json") or "{}"
    try:
        pol = json.loads(raw).get("review") or {}
    except (ValueError, AttributeError):
        pol = {}
    who = getattr(a, "review", "") or (pol.get(a.role) if isinstance(pol, dict) else "") or ""
    if who:
        need_role(who)
        if who == a.role:
            raise SystemExit(f"role:{a.role} can't review its own work: name another role with --review")
    return who


def reviewer_of(t: dict[str, Any]) -> str:
    return next((lb[len(NEEDS_REVIEW):] for lb in labels_of(t) if lb.startswith(NEEDS_REVIEW)), "")


def verdict(hub: Hub, n: int, reviewer: str) -> dict[str, Any] | None:
    """The reviewer's latest verdict on a ticket, from its review comments."""
    last = None
    for c in hub.api(f"issues/{n}/comments?per_page=100") or []:
        m = REVIEW.search(c.get("body") or "")
        try:
            data = json.loads(m.group(1)) if m else None
        except ValueError:
            data = None
        if isinstance(data, dict) and data.get("by") == reviewer and data.get("verdict") in VERDICTS:
            last = data
    return last


def cmd_review(a: argparse.Namespace, hub: Hub) -> int:
    need_role(a.by)
    t = hub.issue(a.n)
    want = reviewer_of(t)
    if a.by == role_of(t):
        print(f"refused: role:{a.by} owns #{a.n}; a review must come from another role")
        return REFUSED
    if want and want != a.by:
        print(f"refused: #{a.n} is waiting on role:{want}'s review, not role:{a.by}'s")
        return REFUSED
    data = {"by": a.by, "verdict": a.verdict}
    hub.comment(a.n, f"<!-- s2s:review {json.dumps(data)} -->\n**Review by role:{a.by}: {a.verdict}**\n\n{quote(a.note)}")
    if not want:
        hub.label(a.n, NEEDS_REVIEW + a.by)
    hub.record(a.n, a.by, "reviewed", f"{a.verdict}: {a.note}")
    print(f"#{a.n}: role:{a.by} {a.verdict}" + ("; the owner may finish it" if a.verdict == "approved" else
                                                 "; the owner changes it and asks again"))
    return OK


def cmd_escalate(a: argparse.Namespace, hub: Hub) -> int:
    need_role(a.by)
    boss = REPORTS_TO.get(a.by, "chief-of-staff")
    hub.label(a.n, ESCALATED + boss)
    who = "the founder" if boss == "founder" else f"role:{boss}"
    hub.comment(a.n, f"**Escalated by role:{a.by} to {who}**\n\n{quote(a.why)}")
    hub.record(a.n, a.by, "escalated", a.why, to=boss)
    print(f"#{a.n} escalated to {who}" + ("; it is in the founder's Needs you list" if boss == "founder" else
                                         f"; it is in `queue {boss}`"))
    return OK


PLAN_FOR = re.compile(r"\*\*Plan for:\*\* #(\d+)")
PLAN_ITEMS = re.compile(r"\*\*Sub-tickets:\*\* (.*)")


def plan_gate_on(root: Path) -> bool:
    return (approval.policy(root)["gates"].get("plan") or {}).get("mode") == "ask"


def latest_plan(hub: Hub, parent: int) -> dict[str, Any] | None:
    """The newest plan request for a parent: its number, decision and the sub-tickets it lists."""
    found = [i for i in hub.tickets("all", approval.LABEL) if "gate:plan" in labels_of(i)
             and (PLAN_FOR.search(i.get("body") or "") or [None, ""])[1] == str(parent)]
    if not found:
        return None
    req = max(found, key=lambda i: i["number"])
    who = approval.founders(approval.policy(hub_root(hub)), hub.repo)
    comments = hub.api(f"issues/{req['number']}/comments?per_page=100") or []
    items = numbers((PLAN_ITEMS.search(req.get("body") or "") or [None, ""])[1])
    return {"number": req["number"], "url": req.get("html_url", ""), "items": items, **approval.decide(comments, who)}


def hub_root(hub: Hub) -> Path:
    return getattr(hub, "root", s.ROOT)


def plan_refusal(hub: Hub, t: dict[str, Any]) -> str:
    """Why a sub-ticket may not be claimed yet under the plan gate; empty when it may."""
    parents = links(t.get("body", ""))["parent"]
    if not parents or not plan_gate_on(hub_root(hub)):
        return ""
    plan = latest_plan(hub, parents[0])
    if plan is None:
        return f"#{parents[0]}'s plan isn't approved yet: its owner runs `tickets.py plan {parents[0]}` first"
    if plan["state"] != "approved":
        return f"#{parents[0]}'s plan (#{plan['number']}) is {plan['state']}, not approved"
    if t["number"] not in plan["items"]:
        return f"#{t['number']} isn't in #{parents[0]}'s approved plan (#{plan['number']}): ask again with the new plan"
    return ""


def cmd_plan(a: argparse.Namespace, hub: Hub) -> int:
    need_role(a.by)
    parent = hub.issue(a.n)
    kids = [k for k in hub.children(a.n) if k.get("state") == "open"]
    if not kids:
        print(f"refused: #{a.n} has no open sub-tickets to plan")
        return REFUSED
    lines = [f"- #{k['number']} role:{role_of(k) or '?'}: {k.get('title', '')}" for k in kids]
    prev = latest_plan(hub, a.n)
    body = "\n".join([
        f"**Gate:** `plan`: start work on #{a.n}'s sub-tickets", f"**Requested by:** role:{a.by}",
        f"**Scope:** plan for #{a.n}" + (f", revision after #{prev['number']}" if prev else ""),
        f"**Plan for:** #{a.n}", f"**Sub-tickets:** {', '.join('#' + str(k['number']) for k in kids)}", "",
        f"## The plan for #{a.n}: {parent.get('title', '')}", *lines, "", "## Why this plan", quote(a.note or "(not given)"), "",
        "## Founder: reply with one line",
        "- `/approve`: the sub-tickets above may start", "- `/revise <what to change>`", "- `/reject <reason>`", "",
        "Until you approve, none of these sub-tickets can be claimed. A changed plan is a new request."])
    req = hub.api("issues", "-X", "POST", payload={"title": f"[approval] Plan for #{a.n}: {parent.get('title', '')}"[:200],
                                                    "body": body, "labels": [approval.LABEL, "gate:plan"]})
    hub.record(a.n, a.by, "plan requested", f"{len(kids)} sub-tickets, approval #{req['number']}")
    print(f"#{req['number']} {req.get('html_url', '')}\nWaiting for the founder: no sub-ticket of #{a.n} can be claimed until then.")
    return OK


def cmd_claim(a: argparse.Namespace, hub: Hub) -> int:
    need_role(a.role)
    t = hub.issue(a.n)
    if t.get("state") != "open":
        print(f"refused: #{a.n} is closed")
        return REFUSED
    if role_of(t) and role_of(t) != a.role:
        print(f"refused: #{a.n} belongs to role:{role_of(t)}; ask for a hand-off instead")
        return REFUSED
    open_blockers = [b for b in links(t.get("body", ""))["blocked by"] if hub.issue(b).get("state") == "open"]
    if open_blockers:
        print(f"refused: #{a.n} is blocked by {', '.join(f'#{b}' for b in open_blockers)}")
        return REFUSED
    why_not = plan_refusal(hub, {**t, "number": a.n})
    if why_not:
        print(f"refused: {why_not}")
        return REFUSED
    who = f"role:{a.role}"
    current = hub.lock(a.n, who)
    if current is not None:
        print(f"refused: #{a.n} is already claimed by {current}; pick another ticket (`queue {a.role}`)")
        return REFUSED
    hub.label(a.n, CLAIMED)
    # The ref and the label carry the claim; a comment on the ticket would only email the founder.
    hub.record(a.n, a.role, "claimed", a.why or "starting work", on_ticket=False)
    print(f"claimed #{a.n} for {who}: {t.get('title', '')}")
    return OK


def owns(hub: Hub, n: int, role: str) -> bool:
    """Only the claim holder, or the ticket's own role when nobody holds it, may release, hand off or finish it."""
    need_role(role)
    current = hub.holder(n)
    if current is not None and current != f"role:{role}":
        print(f"refused: #{n} is claimed by {current}, not role:{role}")
        return False
    owner = role_of(hub.issue(n))
    if current is None and owner and owner != role:
        print(f"refused: #{n} belongs to role:{owner}, not role:{role}")
        return False
    return True


def cmd_release(a: argparse.Namespace, hub: Hub) -> int:
    if not owns(hub, a.n, a.role):
        return REFUSED
    hub.unlock(a.n)
    hub.unlabel(hub.issue(a.n), CLAIMED)
    hub.record(a.n, a.role, "released", a.why or "stopping; the ticket is free to claim")
    print(f"released #{a.n}")
    return OK


def cmd_handoff(a: argparse.Namespace, hub: Hub) -> int:
    need_role(a.to)
    if not owns(hub, a.n, a.by):
        return REFUSED
    t = hub.issue(a.n)
    hub.unlock(a.n)
    hub.unlabel(t, CLAIMED, *[lb for lb in labels_of(t) if lb.startswith("role:") and lb != f"role:{a.to}"])
    hub.label(a.n, f"role:{a.to}")
    hub.record(a.n, a.by, "handed off", a.note, to=a.to)
    print(f"#{a.n} handed to role:{a.to}")
    return OK


def cmd_block(a: argparse.Namespace, hub: Hub, add: bool) -> int:
    need_role(a.by)
    if a.on == a.n:
        print(f"refused: #{a.n} can't block itself")
        return REFUSED
    t = hub.issue(a.n)
    blockers = set(links(t.get("body", ""))["blocked by"])
    blockers = blockers | {a.on} if add else blockers - {a.on}
    hub.api(f"issues/{a.n}", "-X", "PATCH", payload={"body": set_blockers(t.get("body", ""), sorted(blockers))})
    still = [b for b in blockers if hub.issue(b).get("state") == "open"]
    if still:
        hub.label(a.n, BLOCKED)
    else:
        hub.unlabel(t, BLOCKED)
    hub.record(a.n, a.by, "blocked" if add else "unblocked", a.why, on=a.on)
    print(f"#{a.n} blocked by: {', '.join(f'#{b}' for b in sorted(blockers)) or 'nothing'}")
    return OK


def cmd_done(a: argparse.Namespace, hub: Hub) -> int:
    if not owns(hub, a.n, a.role):
        return REFUSED
    t = hub.issue(a.n)
    want = reviewer_of(t)
    if want:
        v = verdict(hub, a.n, want)
        if not v or v["verdict"] != "approved":
            state = "asked for changes" if v else "not reviewed it yet"
            print(f"refused: #{a.n} needs role:{want}'s review, and role:{want} has {state}. "
                  f"Hand it over with `handoff {a.n} --to {want}` or ask on the ticket.")
            return REFUSED
    hub.record(a.n, a.role, "done", a.note)
    hub.api(f"issues/{a.n}", "-X", "PATCH", payload={"state": "closed", "state_reason": "completed"})
    return after_close(hub, t, a.role)


def after_close(hub: Hub, t: dict[str, Any], by: str) -> int:
    n = t["number"]
    hub.unlock(n)
    hub.unlabel(t, CLAIMED)
    woken = hub.wake(n, by)
    print(f"#{n} closed" + (f"; unblocked {', '.join(f'#{w}' for w in woken)}" if woken else ""))
    for parent in links(t.get("body", ""))["parent"]:
        kids = hub.children(parent)
        if kids and all(k["number"] == n or k.get("state") == "closed" for k in kids):
            hub.record(parent, by, "sub-tickets done", "Every sub-ticket is closed; the parent's role checks the"
                       " goal and closes it, or opens what's missing.")
    return OK


def cmd_closed(a: argparse.Namespace, hub: Hub) -> int:
    t = hub.issue(a.n)
    if t.get("state") != "closed":
        print(f"#{a.n} is open: nothing to do")
        return OK
    return after_close(hub, t, "ci")


def cmd_queue(a: argparse.Namespace, hub: Hub) -> int:
    need_role(a.role)
    mine = [t for t in hub.tickets("open") if role_of(t) == a.role]
    ready = [t for t in mine if CLAIMED not in labels_of(t) and BLOCKED not in labels_of(t)]
    for t in ready:
        print(f"#{t['number']} {t.get('title', '')}")
    rest = len(mine) - len(ready)
    print(f"{len(ready)} ready for role:{a.role}" + (f"; {rest} claimed or blocked" if rest else ""))
    everything = hub.tickets("open")
    for t in everything:
        if reviewer_of(t) == a.role and role_of(t) != a.role:
            print(f"review: #{t['number']} {t.get('title', '')} (role:{role_of(t)})")
        if ESCALATED + a.role in labels_of(t):
            print(f"escalated to you: #{t['number']} {t.get('title', '')} (role:{role_of(t)})")
    return OK


def cmd_tree(a: argparse.Namespace, hub: Hub) -> int:
    def line(t: dict[str, Any]) -> str:
        flags = [f for f in (CLAIMED, BLOCKED) if f in labels_of(t)]
        return f"#{t['number']} [{t.get('state')}] role:{role_of(t) or '?'} {t.get('title', '')}" + \
            (f" ({', '.join(flags)})" if flags else "")
    print(line(hub.issue(a.n)))
    for k in hub.children(a.n):
        print("  " + line(k))
    return OK


def cmd_log(a: argparse.Namespace, hub: Hub) -> int:
    logs = hub.tickets("all", LOG)
    rows = parse_log(hub.api(f"issues/{logs[0]['number']}/comments?per_page=100") or []) if logs else []
    rows = [r for r in rows if (not a.role or r.get("role") == a.role) and (not a.ticket or r.get("ticket") == a.ticket)]
    for r in rows[-a.limit:]:
        to = f" → role:{r['to']}" if r.get("to") else ""
        print(f"{r['at'][:16]} {r.get('role')} {r.get('action')} #{r.get('ticket')}{to}: {r['why'].splitlines()[0] if r['why'] else ''}")
    if not rows:
        print("No activity yet.")
    return OK


def main(argv: list[str] | None = None) -> int:
    common = argparse.ArgumentParser(add_help=False)
    common.add_argument("--root", type=Path, default=s.ROOT, help=argparse.SUPPRESS)
    ap = argparse.ArgumentParser(description="Agent coordination through GitHub issues")
    sub = ap.add_subparsers(dest="cmd", required=True)
    p = sub.add_parser("new", parents=[common])
    p.add_argument("role")
    p.add_argument("--title", required=True)
    p.add_argument("--goal", required=True)
    p.add_argument("--done-when", default="")
    p.add_argument("--why", default="")
    p.add_argument("--parent", type=int)
    p.add_argument("--objective", default="", help="the founder/goals.json objective it serves, e.g. O1")
    p.add_argument("--initiative", default="", help="the founder/goals.json initiative it serves, e.g. I1")
    p.add_argument("--stage", type=int, help="the playbook stage whose gate it works toward: label stage:<n>")
    p.add_argument("--blocked-by", type=int, nargs="*")
    p.add_argument("--by", default="")
    p.add_argument("--review", default="", help="the role that reviews it before done; 'none' for no review")
    p.add_argument("--dry-run", action="store_true")
    for name in ("claim", "release", "done"):
        p = sub.add_parser(name, parents=[common])
        p.add_argument("n", type=int)
        p.add_argument("--role", required=True)
        if name == "done":
            p.add_argument("--note", required=True)
        else:
            p.add_argument("--why", default="")
    p = sub.add_parser("handoff", parents=[common])
    p.add_argument("n", type=int)
    p.add_argument("--to", required=True)
    p.add_argument("--note", required=True)
    p.add_argument("--by", required=True)
    for name in ("block", "unblock"):
        p = sub.add_parser(name, parents=[common])
        p.add_argument("n", type=int)
        p.add_argument("--on", type=int, required=True)
        p.add_argument("--why", default="")
        p.add_argument("--by", required=True)
    p = sub.add_parser("review", parents=[common])
    p.add_argument("n", type=int)
    p.add_argument("--verdict", required=True, choices=VERDICTS)
    p.add_argument("--by", required=True)
    p.add_argument("--note", required=True)
    p = sub.add_parser("escalate", parents=[common])
    p.add_argument("n", type=int)
    p.add_argument("--by", required=True)
    p.add_argument("--why", required=True)
    p = sub.add_parser("plan", parents=[common])
    p.add_argument("n", type=int)
    p.add_argument("--by", required=True)
    p.add_argument("--note", default="")
    sub.add_parser("queue", parents=[common]).add_argument("role")
    sub.add_parser("tree", parents=[common]).add_argument("n", type=int)
    sub.add_parser("closed", parents=[common]).add_argument("n", type=int)
    p = sub.add_parser("log", parents=[common])
    p.add_argument("--role", default="")
    p.add_argument("--ticket", type=int)
    p.add_argument("--limit", type=int, default=30)
    a = ap.parse_args(argv)
    repo = repo_name(a.root)
    if not repo:
        print("can't tell which GitHub repo this is: nothing done")
        return ERROR
    hub = Hub(repo)
    hub.root = a.root
    run = {"plan": cmd_plan, "review": cmd_review, "escalate": cmd_escalate, "new": cmd_new, "claim": cmd_claim, "release": cmd_release, "handoff": cmd_handoff, "done": cmd_done,
           "block": lambda a, h: cmd_block(a, h, True), "unblock": lambda a, h: cmd_block(a, h, False),
           "queue": cmd_queue, "tree": cmd_tree, "log": cmd_log, "closed": cmd_closed}[a.cmd]
    try:
        return run(a, hub)
    except (subprocess.CalledProcessError, FileNotFoundError, ValueError, KeyError, TypeError) as exc:
        print(f"GitHub unavailable or unexpected reply ({type(exc).__name__}): nothing claimed; check the ticket by hand")
        return ERROR


if __name__ == "__main__":
    sys.exit(main())
